CREATE TABLE IF NOT EXISTS crm_deal_settings(connection_id text PRIMARY KEY REFERENCES whatsapp_connections(id),enabled boolean NOT NULL DEFAULT false,funil_id integer,stage_id integer,user_id integer,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS crm_deals(id uuid PRIMARY KEY,connection_id text NOT NULL REFERENCES whatsapp_connections(id),phone text NOT NULL,client_id text NOT NULL,remote_id text,state text NOT NULL DEFAULT 'queued',remote_status text,value numeric,reference text NOT NULL UNIQUE,payload jsonb,response jsonb,error text,next_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,phone));
CREATE INDEX IF NOT EXISTS crm_deals_pending_idx ON crm_deals(next_at) WHERE state IN ('queued','uncertain');
CREATE TABLE IF NOT EXISTS crm_deal_actions(id uuid PRIMARY KEY,deal_id uuid NOT NULL REFERENCES crm_deals(id),request_id text NOT NULL,desired jsonb NOT NULL,status text NOT NULL,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(deal_id,request_id));
CREATE UNIQUE INDEX IF NOT EXISTS crm_deal_active_action_idx ON crm_deal_actions(deal_id) WHERE status IN ('sending','uncertain');
